<?php
require_once __DIR__.'/../lib/bootstrap.php'; require_role('teacher','admin');
$uid=(int)current_user()['id'];$eid=get_int('exam_id');$admin=current_user()['role']==='admin';$owner=$admin?'':' AND e.created_by=?';
$params=$admin?[$eid]:[$eid,$uid];$s=db()->prepare("SELECT e.*,s.title subject_title,c.title class_title FROM exams e JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id WHERE e.id=?$owner");$s->execute($params);$exam=$s->fetch();if(!$exam)exit('آزمون پیدا نشد یا دسترسی ندارید.');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post_string('action');if($action==='grant_retake'){$studentId=(int)($_POST['student_id']??0);$reason=post_string('reason',500);$valid=db()->prepare('SELECT 1 FROM class_students WHERE class_id=? AND student_id=?');$valid->execute([(int)$exam['class_id'],$studentId]);if(!$valid->fetchColumn()||$reason===''){flash('error','دانش‌آموز معتبر و دلیل مجوز الزامی است.');}else{$pdo=db();try{$pdo->beginTransaction();$claim=$pdo->prepare('INSERT IGNORE INTO exam_retake_limits(exam_id,student_id) VALUES(?,?)');$claim->execute([$eid,$studentId]);if($claim->rowCount()===0){$pdo->rollBack();flash('error','برای این دانش‌آموز قبلاً یک فرصت مجدد در این آزمون ثبت شده و امکان اعطای دوباره وجود ندارد.');}else{$ins=$pdo->prepare('INSERT INTO exam_retake_grants(exam_id,student_id,granted_by,reason,granted_at) VALUES(?,?,?,?,?)');$ins->execute([$eid,$studentId,$uid,$reason,date('Y-m-d H:i:s')]);audit('grant_exam_retake','exam',$eid);$pdo->commit();flash('success','فرصت مجدد یگانه برای دانش‌آموز ثبت شد.');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','مجوز ثبت نشد؛ migration محدودیت فرصت مجدد را اجرا کنید.');}}redirect('teacher/attempts.php?exam_id='.$eid);}$attemptId=(int)($_POST['attempt_id']??0);$s=db()->prepare('SELECT a.*,u.full_name FROM attempts a JOIN users u ON u.id=a.student_id WHERE a.id=? AND a.exam_id=?');$s->execute([$attemptId,$eid]);$attempt=$s->fetch();if(!$attempt){flash('error','تلاش پیدا نشد.');}else{$pdo=db();$pdo->beginTransaction();try{$pdo->prepare('UPDATE attempts SET revoked_at=?,revoked_by=? WHERE id=? AND exam_id=? AND revoked_at IS NULL')->execute([date('Y-m-d H:i:s'),$uid,$attemptId,$eid]);audit('revoke','attempt',$attemptId);$pdo->commit();flash('success','تلاش دانش‌آموز بازنشانی شد و سابقهٔ آن حفظ گردید.');}catch(Throwable $e){$pdo->rollBack();flash('error','بازنشانی تلاش انجام نشد.');}}redirect('teacher/attempts.php?exam_id='.$eid);}
$s=db()->prepare('SELECT a.*,u.full_name,u.mobile,EXISTS(SELECT 1 FROM exam_retake_limits rl WHERE rl.exam_id=a.exam_id AND rl.student_id=a.student_id) retake_already_granted FROM attempts a JOIN users u ON u.id=a.student_id WHERE a.exam_id=? ORDER BY u.full_name,a.attempt_no');$s->execute([$eid]);$attempts=$s->fetchAll();$roster=db()->prepare('SELECT u.id,u.full_name,u.mobile,EXISTS(SELECT 1 FROM exam_retake_limits rl WHERE rl.exam_id=? AND rl.student_id=u.id) retake_already_granted FROM class_students cs JOIN users u ON u.id=cs.student_id WHERE cs.class_id=? ORDER BY u.full_name');$roster->execute([$eid,(int)$exam['class_id']]);$students=$roster->fetchAll();$title='مدیریت تلاش‌ها';require __DIR__.'/../partials/header.php';?><div class="card class-toolbar"><div><span class="eyebrow">مدیریت آزمون</span><h1>تلاش‌های دانش‌آموزان</h1><p class="muted"><?=e($exam['title'])?> — <?=e($exam['subject_title'])?> — <?=e($exam['class_title'])?></p></div><a class="btn btn-light" href="<?=e(url('teacher/exams.php?id='.$eid))?>">بازگشت به آزمون</a></div><div class="card"><h2>اعطای فرصت مجدد موردی</h2><p class="muted">هر دانش‌آموز فقط یک تلاش عادی و حداکثر یک فرصت مجدد در هر آزمون دارد. پس از اعطای فرصت، امکان اعطای دوباره وجود ندارد؛ نمرهٔ بهتر ملاک نهایی خواهد بود.</p><form method="post" class="grid grid-3"><?=csrf_field()?> <input type="hidden" name="action" value="grant_retake"><div class="form-group"><label>دانش‌آموز</label><select name="student_id" required><option value="">انتخاب کنید</option><?php foreach($students as $student):?><option value="<?=(int)$student['id']?>" <?=!empty($student['retake_already_granted'])?'disabled':''?>><?=e($student['full_name'])?> — <?=e($student['mobile'])?><?=!empty($student['retake_already_granted'])?' — فرصت مجدد قبلاً اعطا شده':''?></option><?php endforeach;?></select></div><div class="form-group"><label>دلیل</label><input name="reason" maxlength="500" required placeholder="مثلاً اختلال فنی"></div><div class="form-group" style="display:flex;align-items:end"><button class="btn btn-primary">ثبت فرصت مجدد</button></div></form></div><div class="card"><p class="muted">فرصت مجدد جدا از بازنشانی سابقه است؛ اعطای آن نمرهٔ تلاش قبلی را حفظ می‌کند و دلیل باید ثبت شود.</p><table class="table"><thead><tr><th>دانش‌آموز</th><th>تلاش</th><th>شروع</th><th>ثبت</th><th>نمره</th><th>درصد</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($attempts as $a):$revoked=!empty($a['revoked_at']);?><tr><td><?=e($a['full_name'])?><br><small><?=e($a['mobile'])?></small></td><td><?=e((string)$a['attempt_no'])?> از <?=e((string)($exam['max_attempts']??1))?></td><td><?=e($a['started_at'])?></td><td><?=e($a['submitted_at']??'—')?></td><td><?=format_score($a['score']??0)?> / <?=format_score($exam['total_score'])?></td><td><?=format_score($a['percentage']??0)?>%</td><td><?=e($revoked?'بازنشانی‌شده':$a['status'])?></td><td><?php if(!$revoked):?><a class="btn btn-sm btn-light" href="<?=e(url('student/result.php?id='.$a['id']))?>" target="_blank">کارنامه</a><?php if(empty($a['retake_already_granted'])):?><form method="post" style="display:inline" onsubmit="const r=prompt('دلیل اعطای فرصت مجدد را وارد کنید:');if(r===null||!r.trim())return false;this.elements.reason.value=r.trim();return confirm('یک فرصت مجدد برای این دانش‌آموز ثبت شود؟ سابقه و نمرهٔ قبلی حفظ می‌شود.')"><?=csrf_field()?> <input type="hidden" name="action" value="grant_retake"><input type="hidden" name="student_id" value="<?=(int)$a['student_id']?>"><input type="hidden" name="reason" value=""><button class="btn btn-sm btn-warning">فرصت مجدد</button></form><?php else:?><span class="badge warning">فرصت مجدد قبلاً اعطا شده</span><?php endif;?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
